select id, name, name_en, slug, sort_order, image_url, description, description_en from jsonb_populate_recordset(null::public.categories, $json$[{"id":"3041931d-879b-507d-a2d4-738bcf47c429","name":"تلوين للأطفال","name_en":"Coloring for kids","slug":"تلوين-للأطفال","sort_order":1,"image_url":"images/categories/coloring.jpg","description":"صفحات تلوين برسومات أصلية وخطوط عريضة واضحة، جاهزة للطباعة بمقاس A4.","description_en":"Original coloring pages with bold, clear lines, ready to print on A4."},{"id":"34c5e974-ceb6-53ae-bb1e-69f9c1b1efcd","name":"قصص وأنشطة","name_en":"Stories & activities","slug":"قصص-وأنشطة","sort_order":2,"image_url":"images/categories/kids.jpg","description":"قصص مصوّرة ملوّنة وكتب أنشطة يتعلّم بها الطفل وهو يلعب: توصيل ومطابقة وأشكال ومتاهات وقص ولصق.","description_en":"Colorful picture stories and activity books: connect the dots, matching, shapes, mazes, cut and paste."},{"id":"aa77bcfe-be93-5dea-a57a-750879195d56","name":"طلاب الابتدائي","name_en":"Primary students","slug":"طلاب-الابتدائي","sort_order":3,"image_url":"images/categories/students.jpg","description":"أوراق عمل للمواد الدراسية من الصف الأول إلى الرابع، مع صفحات الحلول.","description_en":"Worksheets for grades 1 to 4 in every subject, with answer pages."},{"id":"59351792-b075-5185-a325-51aefe4efd78","name":"للمعلمات","name_en":"For teachers","slug":"للمعلمات","sort_order":4,"image_url":"images/categories/teachers.jpg","description":"مواد جاهزة للفصل: شهادات ولوحات تحفيز وخطط ومتابعة وبطاقات أنشطة.","description_en":"Ready classroom materials: certificates, reward charts, planners and activity cards."},{"id":"559ad510-eda3-515e-b33e-cfab93634d52","name":"عروض تقديمية","name_en":"Slide decks","slug":"عروض-تقديمية","sort_order":5,"image_url":"images/categories/slides.jpg","description":"دروس جاهزة للعرض بصيغة PowerPoint، قابلة للتعديل، مع ملاحظات للمعلمة تحت كل شريحة.","description_en":"Ready-to-teach lessons in editable PowerPoint, with teacher notes under every slide."},{"id":"2aeb0f7b-b969-5256-8f7a-e5a8d4e4d331","name":"حزم التوفير","name_en":"Money-saving bundles","slug":"حزم-التوفير","sort_order":6,"image_url":"images/categories/bundles.jpg","description":"ملفات أكثر بسعر أقل: كل ملفات القسم في طلب واحد.","description_en":"More files for less: a whole section in one order."}]$json$::jsonb)
