update public.store_settings set config = $json${"name":"حروف وألوان","logo_url":"images/logo-huroof.png","texts":{"announce_show":true,"announce_text":"جديد في المتجر: أوراق عمل المواد الدراسية للصفوف 1–4، وعروض تقديمية جاهزة للمعلمات."},"order":{"whatsapp":"96877336242"},"contact":{"share_url":"https://a3r-om.github.io/ATHR/huroof/","faq":[{"q":"كيف يصلني الملف؟","a":"بعد ما ترسل الطلب على واتساب ونؤكد الدفع، نرسل لك الملفات في نفس المحادثة: أوراق العمل والقصص بصيغة PDF، والعروض التقديمية بصيغة PowerPoint."},{"q":"هل أحتاج برنامجاً خاصاً لفتح الملفات؟","a":"لا. ملفات PDF تفتح على أي جوال أو كمبيوتر، ويمكن طباعتها مباشرة أو من أي مكتبة. والعروض التقديمية تفتح في PowerPoint أو Keynote أو Google Slides."},{"q":"هل أقدر أعدّل العروض التقديمية؟","a":"نعم، العروض قابلة للتعديل بالكامل: النصوص والصور والألوان. وتحت كل شريحة ملاحظات للمعلمة تشرح طريقة تقديمها في الحصة."},{"q":"هل الملفات ملوّنة أم أبيض وأسود؟","a":"صفحات التلوين وأوراق العمل بالأبيض والأسود لتوفير الحبر، والقصص والشهادات واللوحات ملوّنة، وكلها تُطبع جيداً على أي طابعة."},{"q":"ما مقاس الطباعة؟","a":"كل ملفات PDF بمقاس A4، والشهادات وبعض جداول المعلمة بالعرض. والعروض التقديمية بمقاس الشاشة العريضة 16:9."},{"q":"هل في الملفات حلول؟","a":"نعم، ملفات المواد الدراسية الأربع، وجدول الضرب، والقراءة والفهم، والكسور، وكتاب «العب وتعلّم»، وبطاقات الأنشطة، كلها فيها صفحات حلول في آخرها."},{"q":"هل أقدر أطبع الملف أكثر من مرة؟","a":"نعم، تطبعه كلما احتجت لاستخدامك الشخصي أو لطلاب فصلك. لا يُسمح بإعادة بيع الملف أو نشره."},{"q":"هل أقدر أجرّب قبل الشراء؟","a":"نعم، اطلب صفحة مجانية من أي ملف على واتساب، أو افتح الملف هنا لترى صفحات منه."},{"q":"كيف أدفع؟","a":"نرسل لك المبلغ وطريقة الدفع على واتساب مع تأكيد طلبك."}]},"en":{"texts":{"announce_text":"New in the store: worksheets for grades 1–4 in every subject, and ready slide decks for teachers."}}}$json$::jsonb where id = 1;
