select code, owner, kind, value, min_total, ends_at, max_uses, enabled from jsonb_populate_recordset(null::public.coupons, $json$[{"code": "HUROOF10", "owner": null, "kind": "pct", "value": 10, "min_total": 0, "ends_at": null, "max_uses": null, "enabled": false}]$json$::jsonb)
on conflict (code) do nothing;
